import React,{useEffect,useMemo,useState} from "react";
import{createRoot}from"react-dom/client";
import"./styles.css";
import { supabase, get, money, norm } from "./lib/api.js";
import { readCart, addCart, removeCart, clearCart } from "./lib/cart.js";
